SmsMockupPage::SmsMockupPage(RuntimeFeedbackState* feedbackState) :
    feedbackState_(feedbackState),
    strobe(Name(), StrobeInfo {}, 1024964660204535383U),
    smsStations(),
    smsSelectBox(),
    smsHeader(),
    smsSelected(),
    smsStatus(),
    osbLegends()
{
}

bool SmsMockupPage::IsActive() const noexcept
{
    return feedbackState_ != nullptr && feedbackState_->IsPageActive(GeneratedId());
}

void SmsMockupPage::Run() noexcept
{
    strobe.ClearDirty();
    smsStations.ClearDirty();
    smsSelectBox.ClearDirty();
    smsHeader.ClearDirty();
    smsSelected.ClearDirty();
    smsStatus.ClearDirty();
    osbLegends.ClearDirty();
}

void SmsMockupPage::Initialize() noexcept
{
    strobe.ResetToAuthored();
    smsStations.ResetToAuthored();
    smsSelectBox.ResetToAuthored();
    smsHeader.ResetToAuthored();
    smsSelected.ResetToAuthored();
    smsStatus.ResetToAuthored();
    osbLegends.ResetToAuthored();
}

std::size_t SmsMockupPage::AppendCommands(std::vector<mfd::UserCommand>& commands)
{
    std::size_t count = 0;

    count += strobe.AppendCommands(commands) ? 1U : 0U;
    count += smsStations.AppendCommands(commands) ? 1U : 0U;
    count += smsSelectBox.AppendCommands(commands) ? 1U : 0U;
    count += smsHeader.AppendCommands(commands) ? 1U : 0U;
    count += smsSelected.AppendCommands(commands) ? 1U : 0U;
    count += smsStatus.AppendCommands(commands) ? 1U : 0U;
    count += osbLegends.AppendCommands(commands) ? 1U : 0U;

    return count;
}

std::size_t SmsMockupPage::AppendShutdownCommands(std::vector<mfd::UserCommand>& commands, std::string statusText)
{
    std::size_t count = 0;

    SetStatusCaption(std::move(statusText));
    count += AppendCommands(commands);


    return count;
}

void SmsMockupPage::SetStatusCaption(std::string value)
{
    smsStatus.StatusText().SetText(std::move(value));
}

