AgMockupPage::AgMockupPage(RuntimeFeedbackState* feedbackState) :
    feedbackState_(feedbackState),
    strobe(Name(), StrobeInfo {}, 12522798620474048056U),
    agBombSymbol(),
    agHeader(),
    agProfile(),
    agStatus(),
    osbLegends()
{
}

bool AgMockupPage::IsActive() const noexcept
{
    return feedbackState_ != nullptr && feedbackState_->IsPageActive(GeneratedId());
}

void AgMockupPage::Run() noexcept
{
    strobe.ClearDirty();
    agBombSymbol.ClearDirty();
    agHeader.ClearDirty();
    agProfile.ClearDirty();
    agStatus.ClearDirty();
    osbLegends.ClearDirty();
}

void AgMockupPage::Initialize() noexcept
{
    strobe.ResetToAuthored();
    agBombSymbol.ResetToAuthored();
    agHeader.ResetToAuthored();
    agProfile.ResetToAuthored();
    agStatus.ResetToAuthored();
    osbLegends.ResetToAuthored();
}

std::size_t AgMockupPage::AppendCommands(std::vector<mfd::UserCommand>& commands)
{
    std::size_t count = 0;

    count += strobe.AppendCommands(commands) ? 1U : 0U;
    count += agBombSymbol.AppendCommands(commands) ? 1U : 0U;
    count += agHeader.AppendCommands(commands) ? 1U : 0U;
    count += agProfile.AppendCommands(commands) ? 1U : 0U;
    count += agStatus.AppendCommands(commands) ? 1U : 0U;
    count += osbLegends.AppendCommands(commands) ? 1U : 0U;

    return count;
}

std::size_t AgMockupPage::AppendShutdownCommands(std::vector<mfd::UserCommand>& commands, std::string statusText)
{
    std::size_t count = 0;

    SetStatusCaption(std::move(statusText));
    count += AppendCommands(commands);


    return count;
}

void AgMockupPage::SetStatusCaption(std::string value)
{
    agStatus.StatusText().SetText(std::move(value));
}

LhldUi::LhldUi() :
    radar_(&feedbackState_),
    sms_(&feedbackState_),
    nav_(&feedbackState_),
    ag_(&feedbackState_)
{
    window_.ResetToAuthored();
}

bool LhldUi::SendStartup(mfd::CommandClient& client,
                             const mfd::PageViewState& view,
                             std::string statusText)
{
    if (!client.ActivatePage(radar_))
    {
        return false;
    }

    if (!client.SetPageView(radar_, view.center, view.zoom))
    {
        return false;
    }

    std::vector<mfd::UserCommand> commands;
    window_.AppendCommands(commands);
    radar_.SetStatusCaption(std::move(statusText));
    radar_.AppendCommands(commands);
    if (commands.empty())
    {
        return true;
    }

    mfd::CommandBatch batch;
    batch.sequence = 0;
    batch.mappingHash = "7368761abc6c6561bb0c37bb454ca355c7f3375013f588f8e7c13d848cf6b058";
    batch.commands = std::move(commands);
    return client.SendBatch(batch);
}

bool LhldUi::ApplyFeedback(const mfd::StrobeStatusFeedback& feedback)
{
    return feedbackState_.Apply(feedback);
}

bool LhldUi::ApplyFeedback(const mfd::ActivePageFeedback& feedback)
{
    return feedbackState_.Apply(feedback);
}

bool LhldUi::ApplyFeedbackPayload(std::string_view payload, std::string* error)
{
    return feedbackState_.ApplyPayload(payload, error);
}

std::size_t LhldUi::PollFeedback(mfd::IExchangeChannel& channel, const std::size_t maxMessages, std::string* error)
{
    return feedbackState_.Poll(channel, maxMessages, error);
}

std::uint64_t LhldUi::TotalDecodedFeedbackPackets() const noexcept
{
    return feedbackState_.TotalDecodedFeedbackPackets();
}

bool LhldUi::WindowReportedClosing() const noexcept
{
    return feedbackState_.WindowReportedClosing();
}

void LhldUi::Run() noexcept
{
    window_.ClearDirty();
    radar_.Run();
    sms_.Run();
    nav_.Run();
    ag_.Run();
}

void LhldUi::Initialize() noexcept
{
    resetPending_ = true;
    window_.ResetToAuthored();
    radar_.Initialize();
    sms_.Initialize();
    nav_.Initialize();
    ag_.Initialize();
    feedbackState_.Reset();
}

std::vector<mfd::UserCommand> LhldUi::BuildBatch()
{
    std::vector<mfd::UserCommand> commands;
    if (resetPending_)
    {
        commands.emplace_back(mfd::ResetWindowCommand {});
        resetPending_ = false;
    }
    window_.AppendCommands(commands);
    radar_.AppendCommands(commands);
    sms_.AppendCommands(commands);
    nav_.AppendCommands(commands);
    ag_.AppendCommands(commands);
    return commands;
}

std::vector<mfd::UserCommand> LhldUi::BuildResetBatch()
{
    if (!resetPending_)
    {
        Initialize();
    }

    return BuildBatch();
}

mfd::CommandBatch LhldUi::BuildCommandBatch(const std::uint32_t sequence)
{
    mfd::CommandBatch batch;
    batch.sequence = sequence;
    batch.mappingHash = "7368761abc6c6561bb0c37bb454ca355c7f3375013f588f8e7c13d848cf6b058";
    batch.commands = BuildBatch();
    return batch;
}

mfd::CommandBatch LhldUi::BuildResetCommandBatch(const std::uint32_t sequence)
{
    mfd::CommandBatch batch;
    batch.sequence = sequence;
    batch.mappingHash = "7368761abc6c6561bb0c37bb454ca355c7f3375013f588f8e7c13d848cf6b058";
    batch.commands = BuildResetBatch();
    return batch;
}

bool LhldUi::SubmitLatest(mfd::client::LatestBatchPublisher& publisher, const std::uint32_t sequence)
{
    return publisher.SubmitLatest([this, sequence]()
    {
        return BuildCommandBatch(sequence);
    });
}

bool LhldUi::SubmitReset(mfd::client::LatestBatchPublisher& publisher, const std::uint32_t sequence)
{
    return publisher.SubmitLatest([this, sequence]()
    {
        return BuildResetCommandBatch(sequence);
    });
}

std::vector<mfd::UserCommand> LhldUi::BuildShutdownBatch(std::string statusText)
{
    std::vector<mfd::UserCommand> commands;
    if (resetPending_)
    {
        commands.emplace_back(mfd::ResetWindowCommand {});
        resetPending_ = false;
    }
    radar_.AppendShutdownCommands(commands, std::move(statusText));
    sms_.AppendShutdownCommands(commands, std::string {});
    nav_.AppendShutdownCommands(commands, std::string {});
    ag_.AppendShutdownCommands(commands, std::string {});
    return commands;
}

mfd::CommandBatch LhldUi::BuildShutdownCommandBatch(const std::uint32_t sequence, std::string statusText)
{
    mfd::CommandBatch batch;
    batch.sequence = sequence;
    batch.mappingHash = "7368761abc6c6561bb0c37bb454ca355c7f3375013f588f8e7c13d848cf6b058";
    batch.commands = BuildShutdownBatch(std::move(statusText));
    return batch;
}

bool LhldUi::SubmitShutdown(mfd::client::LatestBatchPublisher& publisher,
                              const std::uint32_t sequence,
                              std::string statusText)
{
    return publisher.SubmitLatest([this, sequence, statusText = std::move(statusText)]() mutable
    {
        return BuildShutdownCommandBatch(sequence, std::move(statusText));
    });
}

